import{_ as a,o as t,c as i,a2 as e}from"./chunks/framework.CsGzzEsd.js";const b=JSON.parse('{"title":"商务德语计划","description":"","frontmatter":{"title":"商务德语计划"},"headers":[],"relativePath":"zh/blogs/German/plan.md","filePath":"zh/blogs/German/plan.md"}'),r={name:"zh/blogs/German/plan.md"};function o(h,l,d,n,s,u){return t(),i("div",null,[...l[0]||(l[0]=[e('<h1 id="商务德语学习计划" tabindex="-1">商务德语学习计划 <a class="header-anchor" href="#商务德语学习计划" aria-label="Permalink to &quot;商务德语学习计划&quot;">​</a></h1><blockquote><p><strong>基本假设：</strong> 这是一个实用性、非应试的目标，每周约 <strong>4 小时</strong>。第一个周期为 24 周，优先练习反复出现的职场场景，而不是追求教材的全面覆盖。</p></blockquote><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><p>周期结束时，能够自如地：</p><ul><li>介绍自己的职位、背景、项目和当前重点；</li><li>参加 30 分钟的会议，请求澄清并总结决定；</li><li>写清楚邮件、跟进、进度更新以及礼貌的不同意见；</li><li>做 5–7 分钟的演示并回答可预见的问题；</li><li>进行一段简短的社交或面试对话，不切换成英语。</li></ul><h2 id="每周节奏" tabindex="-1">每周节奏 <a class="header-anchor" href="#每周节奏" aria-label="Permalink to &quot;每周节奏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>安排</th><th style="text-align:right;">时长</th><th>内容</th></tr></thead><tbody><tr><td>2 次输入</td><td style="text-align:right;">每次 35 分钟</td><td>阅读或收听职场德语；积累有用的短语，而不是孤立的单词。</td></tr><tr><td>2 次输出</td><td style="text-align:right;">每次 35 分钟</td><td>写一封邮件或进度说明，并录一段口头回答。</td></tr><tr><td>1 次对话</td><td style="text-align:right;">45–60 分钟</td><td>带纠错地角色扮演本月的职场场景。</td></tr><tr><td>1 次复习</td><td style="text-align:right;">25 分钟</td><td>重复使用已纠正的短语，并更新错误记录。</td></tr></tbody></table><p>建立一个<strong>按功能分类的短语库</strong>：开场、澄清、同意、反对、提议、推迟、总结和结束。</p><h2 id="_24-周路线图" tabindex="-1">24 周路线图 <a class="header-anchor" href="#_24-周路线图" aria-label="Permalink to &quot;24 周路线图&quot;">​</a></h2><h3 id="第-1-个月——职业身份" tabindex="-1">第 1 个月——职业身份 <a class="header-anchor" href="#第-1-个月——职业身份" aria-label="Permalink to &quot;第 1 个月——职业身份&quot;">​</a></h3><ul><li>自我介绍、职责、团队结构和职业经历。</li><li>核心产出：一段自然的 90 秒自我介绍和一份书面职业简介。</li><li>语法修补：语序、常用介词后的格，以及过去时叙述。</li></ul><h3 id="第-2-个月——邮件与消息" tabindex="-1">第 2 个月——邮件与消息 <a class="header-anchor" href="#第-2-个月——邮件与消息" aria-label="Permalink to &quot;第 2 个月——邮件与消息&quot;">​</a></h3><ul><li>请求、安排时间、跟进、附件、截止日期和语气。</li><li>核心产出：五个可复用的邮件模式，每个都套用到一个真实场景中。</li><li>着重简洁的句子和礼貌的情态动词形式，而不是繁复的客套。</li></ul><h3 id="第-3-个月——会议" tabindex="-1">第 3 个月——会议 <a class="header-anchor" href="#第-3-个月——会议" aria-label="Permalink to &quot;第 3 个月——会议&quot;">​</a></h3><ul><li>议程用语、轮流发言、澄清、表达观点、反对和做决定。</li><li>核心产出：主持一场 15 分钟的模拟会议，并在会后发送总结。</li><li>听出立场和待办事项，然后用自己的话转述，而不是逐句翻译。</li></ul><h3 id="第-4-个月——项目与解决问题" tabindex="-1">第 4 个月——项目与解决问题 <a class="header-anchor" href="#第-4-个月——项目与解决问题" aria-label="Permalink to &quot;第 4 个月——项目与解决问题&quot;">​</a></h3><ul><li>进度、依赖、风险、延期、权衡、数据和建议。</li><li>核心产出：每周一次两分钟的项目更新，包含一个风险和一个请求。</li><li>练习解释图表和数字，不必为每句话写稿。</li></ul><h3 id="第-5-个月——演示与说服" tabindex="-1">第 5 个月——演示与说服 <a class="header-anchor" href="#第-5-个月——演示与说服" aria-label="Permalink to &quot;第 5 个月——演示与说服&quot;">​</a></h3><ul><li>结构提示语、比较、强调、证据、提问和异议。</li><li>核心产出：录制一段 5–7 分钟的演示，介绍一个作品集项目。</li><li>根据反馈反复演示，直到表达稳定，而不是背下来。</li></ul><h3 id="第-6-个月——整合" tabindex="-1">第 6 个月——整合 <a class="header-anchor" href="#第-6-个月——整合" aria-label="Permalink to &quot;第 6 个月——整合&quot;">​</a></h3><ul><li>社交、面试、谈判和跨文化职场场景。</li><li>核心产出：一场 30 分钟的模拟，从寒暄过渡到项目讨论，再到跟进邮件。</li><li>根据实际卡壳的地方确定下一个周期，而不是套用通用的等级清单。</li></ul><h2 id="每月反馈循环" tabindex="-1">每月反馈循环 <a class="header-anchor" href="#每月反馈循环" aria-label="Permalink to &quot;每月反馈循环&quot;">​</a></h2><p>每月月底保留四份成果：</p><ol><li>一封修改过的邮件；</li><li>一段录音口语任务；</li><li>五个反复出现的错误；</li><li>十个在不同场景中都用过的高价值短语。</li></ol><p>衡量的是<strong>沟通是否成功</strong>，而不只是正确与否：对方是否理解了请求、决定、风险和下一步行动？</p><h2 id="前七天" tabindex="-1">前七天 <a class="header-anchor" href="#前七天" aria-label="Permalink to &quot;前七天&quot;">​</a></h2><ul><li>[ ] 不看稿录一段两分钟的职业自我介绍。</li><li>[ ] 写一封真实的工作邮件并请人修改。</li><li>[ ] 建立按功能分类的短语库和错误记录。</li><li>[ ] 预约每周固定的对话练习或家教时间。</li><li>[ ] 选一个真实项目，作为六个月口语作品集的主题。</li></ul>',27)])])}const q=a(r,[["render",o]]);export{b as __pageData,q as default};
